class Payments:
    def __init__(self, charge):
        self.charge = charge
        self.receipts = {}
    def submit(self, key, amount):
        if key in self.receipts:
            old_amount, receipt = self.receipts[key]
            if old_amount != amount: raise ValueError('conflicting replay')
            return receipt
        receipt = self.charge(amount)
        self.receipts[key] = (amount, receipt)
        return receipt
